    e_hat = (Ehat_q(2) - Ebar) / Escale;           % ê 取 q50（T-309 §2）

    % ---- G1：分位数门控（T-309 §3，S1/S2 = val P75/P95 字面量）----
    s_q = Ehat_q(3) - Ehat_q(1);                   % q90-q10 [kWh]
    if s_q <= GATE_S1
        K_q = 1;
    elseif s_q >= GATE_S2
        K_q = 0;
    else
        K_q = (GATE_S2 - s_q) / (GATE_S2 - GATE_S1);
    end

    % ---- G2：工况识别门控（workclf_v1，T-308；仅 upstream 可辨识，T-309 修订）----
    Pdec = xnorm(1:10:300);                        % 30x1（归一化域切片，与 T-312 训练口径一致；2026-09 口径修订，原 xP(1:10:300) raw 口径致 int8 标定错配坍缩，AI_MODELING §22）
    c1 = zeros(30, 16);
    for jf = 1:16
        for jt = 1:30
            acc = C1B(jf);
            for kk = 1:5
                jj = jt - 5 + kk;
                if jj >= 1
                    acc = acc + C1W(kk, 1, jf) * Pdec(jj);
                end
            end
            c1(jt, jf) = max(acc, 0);
        end
    end
    p1 = zeros(15, 16);
    for jt = 1:15
        p1(jt, :) = max(c1(2*jt - 1, :), c1(2*jt, :));
    end
    c2 = zeros(15, 32);
    for jf = 1:32
        for jt = 1:15
            acc = C2B(jf);
            for kk = 1:3
                jj = jt - 3 + kk;
                if jj >= 1
                    acc = acc + p1(jj, :) * reshape(C2W(kk, :, jf), 16, 1);
                end
            end
            c2(jt, jf) = max(acc, 0);
        end
    end
    p2 = zeros(7, 32);
    for jt = 1:7
        p2(jt, :) = max(c2(2*jt - 1, :), c2(2*jt, :));
    end
    c3 = zeros(7, 32);
    for jf = 1:32
        for jt = 1:7
            acc = C3B(jf);
            for kk = 1:3
                jj = jt - 3 + kk;
                if jj >= 1
                    acc = acc + p2(jj, :) * reshape(C3W(kk, :, jf), 32, 1);
                end
            end
            c3(jt, jf) = max(acc, 0);
        end
    end
    gfeat = mean(c3, 1)';                          % GAP [32x1]
    s8 = max(F1W' * [xnorm(301); xnorm(302)] + F1B(:), 0);  % [8x1]（归一化 v/accel，口径修订）
    hcl = max(F2W' * [gfeat; s8] + F2B(:), 0);     % [64x1]
    ocl = F3W' * hcl + F3B(:);                     % [7x1]
    [~, cls] = max(ocl);                           % 1..7（1=depart..6=upstream..7=berth）

    % 迟滞状态机（T-309 §4：连续 3 窗同类才切换）
    if cls_eff < 0
        cls_eff = cls; run_cls = cls; run_cnt = 0;
    elseif cls == cls_eff
        run_cls = cls; run_cnt = 0;
    elseif cls == run_cls
        run_cnt = run_cnt + 1;
        if run_cnt >= GATE_M
            cls_eff = cls; run_cnt = 0;
        end
    else
        run_cls = cls; run_cnt = 1;
    end
    if cls_eff == 6                                % 6=upstream（唯一可辨识受限类）
        K_w = 0;
    else
        K_w = 1;
    end

    % ---- GATE_MODE：0=G0 无门控 / 1=G1 / 2=G2 / 3=G3 ----
    if GATE_MODE == 0
        K = 1;
    elseif GATE_MODE == 1
        K = K_q;
    elseif GATE_MODE == 2
        K = K_w;
    else
        K = K_q * K_w;
    end
    e_hat = K * e_hat;
else
    % 回退：权重缺失或输入非有限 -> ê=0（≡law=5 行为，FR-208）
    e_hat = 0;
end
% 与 law=6 v2 完全一致：自适应 λ（SOC_ref 通道）+ 下限钳位 + 单步网格穷举
soc_ref_eff = SOC_ref + K_S * e_hat;
lam = lambda + K_soc * (soc_ref_eff - SOC);
if K_S ~= 0
    lam = max(lam, Lambda_Floor);
end
N = floor(Gen_P_max / ECMS_Grid_dP_kW) + 1;
Pbest = 0;
Jbest = inf;
nb = numel(bsfc_bp);
for i = 1:N
    Pg = (i - 1) * ECMS_Grid_dP_kW;
    Pbat = P_load - ASSUMED_eta_rect * Pg;
    if SOC <= ECMS_SOC_Discharge_Max
        if Pbat > 1e-9
            continue;
        end
        Pbest = Pg;
        break;
    end
    if SOC >= ECMS_SOC_Charge_Min && Pbat < 0
        continue;
    end
    if Pg < 1e-9
        mf = ECMS_Idle_Fuel_kgph / 3600;
    else
        bsfc = bsfc_tbl(1);
        if Pg >= bsfc_bp(nb)
            bsfc = bsfc_tbl(nb);
        elseif Pg > bsfc_bp(1)
            ii = 1;
            while ii < nb - 1 && bsfc_bp(ii + 1) < Pg
                ii = ii + 1;
            end
            w = (Pg - bsfc_bp(ii)) / (bsfc_bp(ii + 1) - bsfc_bp(ii));
            bsfc = bsfc_tbl(ii) + w * (bsfc_tbl(ii + 1) - bsfc_tbl(ii));
        end
        mf = Pg * bsfc / 3.6e6;
    end
    if Pbat > 0
        mbe = Pbat / (ASSUMED_eta_dcdc * ASSUMED_Bat_Eff_Discharge) / 3600;
    else
        mbe = Pbat * (ASSUMED_eta_dcdc * ASSUMED_Bat_Eff_Charge) / 3600;
    end
    J = mf + lam * mbe;
    if J < Jbest
        Jbest = J;
        Pbest = Pg;
    end
end
if SOC <= ECMS_SOC_Discharge_Max && Pbest < 1e-9 && P_load > ASSUMED_eta_rect * Gen_P_max
    Pbest = Gen_P_max;
end
P = Pbest;
Pheld = Pbest;
end
